const input = $json || {};
const query = input.query || {};

const code = query.code || null;
const stateRaw = query.state || "";
const oauthError = query.error || null;

function parseState(raw) {
  try {
    const decoded = Buffer.from(String(raw), "base64").toString("utf8");
    const parsed = JSON.parse(decoded);
    return parsed && typeof parsed === "object" ? parsed : null;
  } catch {
    return null;
  }
}

function isUuid(value) {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(value || ""));
}

const state = parseState(stateRaw);
const agentId = state?.agent_id || null;
const organizationId = state?.organization_id || null;

let error = null;
if (oauthError) error = "google_oauth_denied";
else if (!code) error = "missing_code";
else if (!isUuid(agentId) || !isUuid(organizationId)) error = "invalid_state";

return [{
  json: {
    valid: !error,
    error,
    code,
    agent_id: agentId,
    organization_id: organizationId
  }
}];

const ctx = $("validate_oauth_callback").first().json;
const lookup = $json || {};

const agentValid = lookup.agent_valid === true || lookup.agent_valid === "t" || lookup.agent_valid === "true";

return [{
  json: {
    ...ctx,
    valid: ctx.valid && agentValid,
    error: !agentValid ? "agent_not_found" : ctx.error
  }
}];

const ctx = $("check_agent_valid").first().json;
const tokens = $("exchange_code_for_tokens").first().json;
const userInfo = $("get_google_userinfo").first().json;

function sqlText(value) {
  if (value === undefined || value === null || value === "") return "NULL";
  return "'" + String(value).replace(/'/g, "''") + "'";
}

function sqlUuid(value) {
  const text = String(value || "").trim();
  const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(text);
  if (!isUuid) throw new Error("Invalid uuid in google calendar oauth callback: " + text);
  return "'" + text + "'::uuid";
}

if (!tokens.refresh_token) {
  throw new Error("Google no devolvio refresh_token. La URL de autorizacion debe incluir access_type=offline y prompt=consent.");
}

const expiresAt = new Date(Date.now() + (Number(tokens.expires_in || 3600) * 1000)).toISOString();

const query = `
WITH upsert_conn AS (
  INSERT INTO public.google_calendar_connections
    (organization_id, agent_id, google_email, scope, refresh_token, access_token, access_token_expires_at)
  VALUES (
    ${sqlUuid(ctx.organization_id)},
    ${sqlUuid(ctx.agent_id)},
    ${sqlText(userInfo.email)},
    ${sqlText(tokens.scope)},
    ${sqlText(tokens.refresh_token)},
    ${sqlText(tokens.access_token)},
    ${sqlText(expiresAt)}::timestamptz
  )
  ON CONFLICT (agent_id) DO UPDATE SET
    google_email = EXCLUDED.google_email,
    scope = EXCLUDED.scope,
    refresh_token = EXCLUDED.refresh_token,
    access_token = EXCLUDED.access_token,
    access_token_expires_at = EXCLUDED.access_token_expires_at,
    updated_at = now()
  RETURNING agent_id
),
upd_agent AS (
  UPDATE public.agents
  SET google_calendar_connected = true,
      google_calendar_email = ${sqlText(userInfo.email)}
  WHERE id = ${sqlUuid(ctx.agent_id)}
  RETURNING id
)
SELECT (SELECT agent_id FROM upsert_conn) AS agent_id, (SELECT id FROM upd_agent) AS updated_agent_id;
`;

return [{ json: { ...ctx, upsert_query: query, google_email: userInfo.email } }];

const data = $json || {};
const upstream = $("build_upsert_query").first().json;
const email = upstream.google_email || data.google_email || "";
const redirectUrl = "https://closer.aahumada.com/agents/" + (data.agent_id || "") + "?calendar_connected=1";

const html = `<!DOCTYPE html>
<html lang="es">
<head><meta charset="utf-8"><title>Calendario conectado</title></head>
<body style="font-family: sans-serif; text-align: center; margin-top: 80px;">
  <h2>Listo, tu Google Calendar quedo conectado</h2>
  <p>Cuenta conectada: ${email}</p>
  <p>Redirigiendo de vuelta al panel...</p>
  <script>setTimeout(function () { window.location.href = ${JSON.stringify(redirectUrl)}; }, 1500);</script>
</body>
</html>`;

return [{ json: { html_body: html } }];

const data = $json || {};
const errorMessages = {
  google_oauth_denied: "Cancelaste la conexion con Google o no diste el permiso necesario.",
  missing_code: "Falta el codigo de autorizacion de Google.",
  invalid_state: "El enlace de conexion no es valido o expiro.",
  agent_not_found: "No se encontro el agente al que se quiere conectar el calendario."
};

const message = errorMessages[data.error] || "No se pudo conectar el calendario de Google.";

const html = `<!DOCTYPE html>
<html lang="es">
<head><meta charset="utf-8"><title>No se pudo conectar</title></head>
<body style="font-family: sans-serif; text-align: center; margin-top: 80px;">
  <h2>No se pudo conectar tu Google Calendar</h2>
  <p>${message}</p>
  <p>Vuelve al panel e intenta de nuevo.</p>
</body>
</html>`;

return [{ json: { html_body: html } }];

